<?php
declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$admin=$auth->requireAdmin();$userId=(int)($_GET['id']??0);$target=$db->one('SELECT id,name,email,enabled FROM users WHERE id=?',[$userId]);if(!$target){http_response_code(404);Web::page('Nie znaleziono','<div class="alert danger">Nie znaleziono użytkownika.</div>',$admin);}if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);$appId=(int)($_POST['application_id']??0);$action=(string)($_POST['action']??'');$app=$db->one('SELECT id FROM applications WHERE id=? AND deleted_at IS NULL',[$appId]);if($app){if($action==='grant')$access->grantUser($appId,$userId,(int)$admin['id']);elseif($action==='revoke')$access->revokeUser($appId,$userId,(int)$admin['id']);elseif(in_array($action,['assign_role','remove_role'],true)){$roleId=(int)($_POST['app_role_id']??0);$role=$db->one('SELECT id,name FROM app_roles WHERE id=? AND application_id=?',[$roleId,$appId]);if($role){if($action==='assign_role')$db->execute('INSERT IGNORE INTO app_user_roles(application_id,user_id,app_role_id,created_by) VALUES(?,?,?,?)',[$appId,$userId,$roleId,(int)$admin['id']]);else$db->execute('DELETE FROM app_user_roles WHERE application_id=? AND user_id=? AND app_role_id=?',[$appId,$userId,$roleId]);$audit->write('application.user_role.'.($action==='assign_role'?'assigned':'removed'),'success',(int)$admin['id'],$userId,$appId,null,['role'=>$role['name']]);}}}Web::redirect('/admin/users/'.$userId.'/applications');}$apps=$db->all('SELECT * FROM applications WHERE deleted_at IS NULL ORDER BY name');$rows='';foreach($apps as$app){$appId=(int)$app['id'];$has=$access->hasAccess($userId,$app);$assigned=$access->rolesForUser($userId,$appId);$roles=$db->all('SELECT id,name FROM app_roles WHERE application_id=? ORDER BY name',[$appId]);$options='<option value="">— wybierz rolę —</option>';foreach($roles as$role)$options.='<option value="'.(int)$role['id'].'">'.Web::e($role['name']).'</option>';$rows.='<tr><td><a href="/admin/applications/'.$appId.'"><strong>'.Web::e($app['name']).'</strong></a></td><td><span class="badge '.($has?'ok':'muted').'">'.($has?'Tak':'Nie').'</span></td><td>'.Web::e(implode(', ',$assigned)?:'—').'</td><td><form method="post" class="inline"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="application_id" value="'.$appId.'"><button name="action" value="'.($has?'revoke':'grant').'">'.($has?'Odbierz dostęp':'Nadaj dostęp').'</button></form>';if($roles!==[])$rows.='<form method="post" class="inline"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="application_id" value="'.$appId.'"><select name="app_role_id" required>'.$options.'</select><button name="action" value="assign_role">Przypisz rolę</button><button name="action" value="remove_role">Usuń rolę</button></form>';$rows.='</td></tr>';}$content='<div class="page-head"><div><h1>Aplikacje użytkownika</h1><p>'.Web::e($target['name']).' · '.Web::e($target['email']).'</p></div><a class="button" href="/admin/users/'.$userId.'/attributes">Custom attributes</a></div><div class="table-wrap"><table><thead><tr><th>Aplikacja</th><th>Dostęp</th><th>Role</th><th>Akcje</th></tr></thead><tbody>'.($rows?:'<tr><td colspan="4">Brak aplikacji.</td></tr>').'</tbody></table></div>';Web::page('Aplikacje użytkownika',$content,$admin);
